package com.sivion.api.crm.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="crm_activities") public class Activity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="tenant_id",nullable=false) Long tenantId; @Column(name="customer_id") Long customerId; @Column(name="lead_id") Long leadId; @Column(name="opportunity_id") Long opportunityId;
 @Column(length=30,nullable=false) String type="NOTE"; @Column(length=200,nullable=false) String subject; @Column(length=2000) String description; @Column(name="due_at") Instant dueAt; @Column(name="completed_at") Instant completedAt; @Column(name="assigned_to",length=200) String assignedTo;
 @Column(name="created_at",nullable=false) Instant createdAt; @PrePersist void p(){createdAt=Instant.now();}
 public Long getId(){return id;} public Long getTenantId(){return tenantId;} public void setTenantId(Long v){tenantId=v;} public Long getCustomerId(){return customerId;} public void setCustomerId(Long v){customerId=v;} public Long getLeadId(){return leadId;} public void setLeadId(Long v){leadId=v;} public Long getOpportunityId(){return opportunityId;} public void setOpportunityId(Long v){opportunityId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getSubject(){return subject;} public void setSubject(String v){subject=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Instant getDueAt(){return dueAt;} public void setDueAt(Instant v){dueAt=v;} public Instant getCompletedAt(){return completedAt;} public void setCompletedAt(Instant v){completedAt=v;} public String getAssignedTo(){return assignedTo;} public void setAssignedTo(String v){assignedTo=v;} public Instant getCreatedAt(){return createdAt;}
}
